import path from "node:path";
import { runProgram } from "../../../kernel/node/process.ts";

/** The result of one program run: the exit code, the trimmed output of both streams, and the standard output with no trim. */
export interface Outcome {
  readonly code: number;
  readonly out: string;
  /** The standard output with no trim, for the output that has meaning in its blanks. */
  readonly stdout: string;
}

/** The longest run, in milliseconds, of a program that a command starts. */
const RUN_MAX_MS = 600_000;

/** Runs `file` with `args` in `cwd`. A program that is not found gives code 127. */
export const exec = (cwd: string, file: string, args: string[]): Outcome => {
  try {
    const r = runProgram(file, args, {
      cwd,
      stdin: "ignore",
      stdout: "pipe",
      stderr: "pipe",
      timeout: RUN_MAX_MS,
    });
    const stdout = r.stdout?.toString() ?? "";
    return {
      code: r.exitCode ?? 1,
      stdout,
      out: `${stdout}${r.stderr?.toString() ?? ""}`.trim(),
    };
  } catch (err) {
    return {
      code: 127,
      stdout: "",
      out: err instanceof Error ? err.message : String(err),
    };
  }
};

/** Runs the shell command `command` with `sh -c` in `cwd`. */
export const shell = (cwd: string, command: string): Outcome =>
  exec(cwd, "sh", ["-c", command]);

/** The path that `git rev-parse flag` gives in `cwd`, as an absolute path, or null when git gives none. */
export const gitPath = (cwd: string, flag: string): string | null => {
  const r = exec(cwd, "git", ["rev-parse", flag]);
  return r.code === 0 && r.stdout.trim()
    ? path.resolve(cwd, r.stdout.trim())
    : null;
};

/** True when `cwd` is in a linked git worktree: its git folder is not the common git folder. */
export const inLinkedWorktree = (cwd: string): boolean => {
  const dir = gitPath(cwd, "--git-dir");
  const common = gitPath(cwd, "--git-common-dir");
  return dir !== null && common !== null && dir !== common;
};

/** The SHA of `HEAD` in `cwd`, or the empty string when `cwd` has no commit. */
export const head = (cwd: string): string => {
  const r = exec(cwd, "git", ["rev-parse", "--verify", "--quiet", "HEAD"]);
  return r.code === 0 ? r.stdout.trim() : "";
};
